-- Existing records retain their original authorization semantics. New reread results opt out at creation.
ALTER TABLE "SemanticReview" ADD COLUMN "automaticContactAllowed" BOOLEAN NOT NULL DEFAULT true;
CREATE OR REPLACE VIEW history_display."SemanticReview" AS SELECT t."policyId",t."policyRevision",t."sourceContentHash",t."analysisKey",t."selectedModel",t."ruleHash",t."contextVersion",t."captureId",t."evaluationInput",t."id",t."configId",t."runId",t."revision",t."leaseUntil",t."snapshotHash",t."platform"::text::history_display."Platform" AS "platform",t."platformUserId",t."snapshot",t."rules",t."state",t."score",t."reason",t."context",t."result",t."provider",t."modelVersion",t."isDemo",t."reviewStatus",t."reviewNote",t."reviewedBy",t."reviewedAt",t."version",t."createdAt",t."updatedAt" ,t."automaticContactAllowed" FROM public."SemanticReview" t WHERE NOT history_display.is_archived('SemanticReview',t.id) OR EXISTS (SELECT 1 FROM public."CapturedComment" c WHERE c.id=t."captureId" AND (NOT history_display.is_archived('CapturedComment',c.id) OR EXISTS (SELECT 1 FROM public."CollectionRun" r WHERE r.id=c."lastRunId" AND NOT history_display.is_archived('CollectionRun',r.id))));
